import fs from 'node:fs';import assert from 'node:assert/strict';import {hash,json} from './seal-simple-website-successor.mjs';
const file='CURRENT_CHECKPOINT.json',before=json(file),p=structuredClone(before),root='F:/VisibleMedicine/recovery/checkpoints/20261024-studio-route-index-history';assert(!fs.existsSync(root));assert.equal(p.goal.status,'active');assert.equal(p.activeWork.current.activeExecutionSessions.length,0);assert.equal(p.activeWork.current.ownerPreviewPolicy.restartPermitted,false);
const keys=['pendingNativeSliceCommit','pendingHeadStudySetCommit'],history={schema:'visible-medicine.index-history/1',at:new Date().toISOString(),previousArchive:p.historyArchive,activeWork:{current:{}}};
for(const key of keys){const value=p.activeWork.current[key];assert(value?.integratedInto?.sourceReceipt);history.activeWork.current[key]=structuredClone(value);p.activeWork.current[key]={checkpoint:value.checkpoint,checkpointSha256:value.checkpointSha256,integratedInto:value.integratedInto,detailsAtOriginalJsonPath:'activeWork.current.'+key,detailsIn:root+'/history.json',policy:'Integrated historical proposal; no installation, approval or completion inferred.'};}
fs.mkdirSync(root);fs.copyFileSync(file,root+'/CURRENT_BEFORE.json',fs.constants.COPYFILE_EXCL);fs.writeFileSync(root+'/history.json',JSON.stringify(history,null,2)+'\n',{flag:'wx'});fs.writeFileSync(root+'/field-index.json',JSON.stringify(keys.map(k=>'activeWork.current.'+k),null,2)+'\n',{flag:'wx'});p.historyArchive={path:root+'/history.json',sha256:hash(root+'/history.json'),fieldIndex:root+'/field-index.json',allHistoryRetained:true,priorArchiveIn:'previousArchive',readPolicy:before.historyArchive.readPolicy};
const inverse=structuredClone(p);inverse.historyArchive=history.previousArchive;for(const key of keys)inverse.activeWork.current[key]=history.activeWork.current[key];assert.deepEqual(inverse,before);const text=JSON.stringify(p,null,2)+'\n';assert(Buffer.byteLength(text)<63488);fs.writeFileSync(file,text);fs.copyFileSync(file,root+'/CURRENT_AFTER.json',fs.constants.COPYFILE_EXCL);fs.writeFileSync(root+'/RECEIPT.json',JSON.stringify({at:new Date().toISOString(),beforeSha256:hash(root+'/CURRENT_BEFORE.json'),afterSha256:hash(root+'/CURRENT_AFTER.json'),archivedKeys:keys,wholeInverseVerified:true,goalSafetyPreviewAndProcessPoliciesUnchanged:true},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({bytes:Buffer.byteLength(text),archive:root+'/history.json',wholeInverseVerified:true}));
